insert into public.kids_activity_version (activity_version_id, activity_id, semantic_version, status, release_channel, content_hash, snapshot, schema_version, source_locale, core_v2, risk_level, published_at) values
  ('ACT-0001@1.0.0', 'ACT-0001', '1.0.0', 'draft', 'synthetic-demo', 'sha256:b56f9e656eca831319942909eec967785523627a4a65a412e6718ea3ff3ec404', '{"activityId":"ACT-0001","activityVersionId":"ACT-0001@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":5,"ageMax":10,"participantsMin":1,"participantsMax":4,"minutes":30,"safetyLevel":"A","mess":"low"},"locales":{"en-US":{"title":"Paper Bridge","summary":"Build, test, and improve a paper bridge using the same load each time.","blocks":[{"id":"safety-1","type":"safety_notice","required":true,"payload":{"title":"Adult check","text":"Keep hands and faces away from beneath the bridge. The adult positions the supports and cup."}},{"id":"step-1","type":"instruction","required":true,"payload":{"eyebrow":"Discover · 6 min","title":"Test a flat sheet first","text":"Place one sheet across two supports. Center the empty cup, add one crayon at a time, and record the last stable load."}},{"id":"question-1","type":"question","required":false,"payload":{"prompt":"What changed in the paper just before the bridge failed?"}}]},"es-US":{"title":"Puente de papel","summary":"Construyan, prueben y mejoren un puente de papel usando la misma carga en cada prueba.","blocks":[{"id":"safety-1","type":"safety_notice","required":true,"payload":{"title":"Revisión adulta","text":"Mantengan manos y caras lejos de la zona bajo el puente. El adulto coloca los apoyos y el vaso."}},{"id":"step-1","type":"instruction","required":true,"payload":{"eyebrow":"Descubrir · 6 min","title":"Prueben primero una hoja plana","text":"Coloca una hoja entre dos apoyos. Centra el vaso vacío, añade un crayón por turno y registra la última carga estable."}},{"id":"question-1","type":"question","required":false,"payload":{"prompt":"¿Qué cambió en el papel justo antes de que el puente cediera?"}}]}},"adaptations":[{"id":"ACT-0001-ADAPT-SHORT","summary":{"en-US":"Use one design cycle","es-US":"Usar un solo ciclo de diseño"},"visibleChanges":{"en-US":["Test one folded design after the baseline","Keep the same safety and comparison rules"],"es-US":["Probar un diseño plegado después de la referencia","Mantener las mismas reglas de seguridad y comparación"]},"blocks":{"en-US":[{"id":"safety-1","type":"safety_notice","required":true,"payload":{"title":"Adult check","text":"Keep hands and faces away from beneath the bridge. The adult positions the supports and cup."}},{"id":"step-short","type":"instruction","required":true,"payload":{"eyebrow":"Short version · 18 min","title":"Test one change","text":"Test the flat sheet, choose one fold, and compare both results with the same load."}}],"es-US":[{"id":"safety-1","type":"safety_notice","required":true,"payload":{"title":"Revisión adulta","text":"Mantengan manos y caras lejos de la zona bajo el puente. El adulto coloca los apoyos y el vaso."}},{"id":"step-short","type":"instruction","required":true,"payload":{"eyebrow":"Versión corta · 18 min","title":"Prueben un cambio","text":"Prueben la hoja plana, elijan un pliegue y comparen ambos resultados con la misma carga."}}]}}],"ragChunks":{"en-US":[{"id":"ACT-0001-en-step","label":"Paper Bridge · current step","content":"If the bridge falls immediately, verify that the supports are stable, the gap is 15 cm, and the cup is empty and centered before adding crayons."},{"id":"ACT-0001-en-safety","label":"Paper Bridge · safety","content":"The adult moves supports and centers the cup. Children add one crayon at a time and keep hands and faces out from below."}],"es-US":[{"id":"ACT-0001-es-step","label":"Puente de papel · paso actual","content":"Si el puente cae de inmediato, comprueba que los apoyos estén estables, la distancia sea 15 cm y el vaso esté vacío y centrado."},{"id":"ACT-0001-es-safety","label":"Puente de papel · seguridad","content":"El adulto mueve los apoyos y centra el vaso. Los niños añaden un crayón por turno y no ponen manos ni cara debajo."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0001","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[5,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":4,"sizes":[1,2,3,4]},"time":{"min":20,"max":30,"prep":5,"clean":5},"mess":"low","spaces":["table"],"offline":true},"learn":{"primary":"engineering","secondary":["physics","mathematics"],"goal":"Build, test, and improve a paper bridge using the same load each time.","method":"paper-folding-load","skills":["physics","mathematics"],"concepts":["paper-folding-load"]},"flow":"adult-guided","materials":["paper","books","crayons","cup"],"steps":["safety-1","step-1","question-1"],"safety":{"level":"A","adultLed":true},"adaptations":["ACT-0001-ADAPT-SHORT"],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null),
  ('ACT-0002@1.0.0', 'ACT-0002', '1.0.0', 'draft', 'synthetic-demo', 'sha256:e4f8d851e5d81517b555b8ac23f277deee006f31431ec8fda27f7b6ba789ccfb', '{"activityId":"ACT-0002","activityVersionId":"ACT-0002@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":5,"ageMax":10,"participantsMin":1,"participantsMax":4,"minutes":25,"safetyLevel":"A","mess":"low"},"locales":{"en-US":{"title":"Seed Sorter","summary":"Create a useful rule for sorting seeds, test it, and explain exceptions.","blocks":[{"id":"safety-2","type":"safety_notice","required":true,"payload":{"title":"Not for eating","text":"Use clean, dry seeds as objects only. Keep small pieces away from mouths and younger children."}},{"id":"step-2","type":"instruction","required":true,"payload":{"eyebrow":"Sort · 8 min","title":"Choose one visible rule","text":"Sort the mixed seeds by one property, then ask someone else to infer your rule."}}]},"es-US":{"title":"Clasificador de semillas","summary":"Creen una regla útil para clasificar semillas, pruébenla y expliquen las excepciones.","blocks":[{"id":"safety-2","type":"safety_notice","required":true,"payload":{"title":"No son alimento","text":"Usen semillas limpias y secas solo como objetos. Mantengan las piezas pequeñas lejos de bocas y niños menores."}},{"id":"step-2","type":"instruction","required":true,"payload":{"eyebrow":"Clasificar · 8 min","title":"Elijan una regla visible","text":"Clasifiquen las semillas por una propiedad y pidan a otra persona que deduzca la regla."}}]}},"adaptations":[{"id":"ACT-0002-ADAPT-LESS","summary":{"en-US":"Use two seed types","es-US":"Usar dos tipos de semillas"},"visibleChanges":{"en-US":["Reduce the number of categories"],"es-US":["Reducir el número de categorías"]},"blocks":{"en-US":[{"id":"safety-2","type":"safety_notice","required":true,"payload":{"title":"Not for eating","text":"Keep the dry seeds away from mouths."}},{"id":"step-2a","type":"instruction","required":true,"payload":{"eyebrow":"Short version","title":"Compare two kinds","text":"Choose one visible difference and sort two seed types."}}],"es-US":[{"id":"safety-2","type":"safety_notice","required":true,"payload":{"title":"No son alimento","text":"Mantengan las semillas secas lejos de la boca."}},{"id":"step-2a","type":"instruction","required":true,"payload":{"eyebrow":"Versión corta","title":"Comparen dos tipos","text":"Elijan una diferencia visible y clasifiquen dos tipos de semillas."}}]}}],"ragChunks":{"en-US":[{"id":"ACT-0002-en","label":"Seed Sorter · guidance","content":"If categories overlap, name one observable property and sort every seed using only that property. Exceptions can form a separate unsure group."}],"es-US":[{"id":"ACT-0002-es","label":"Clasificador de semillas · guía","content":"Si las categorías se mezclan, nombren una propiedad observable y clasifiquen cada semilla usando solo esa propiedad. Las excepciones pueden ir en un grupo de dudas."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0002","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[5,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":4,"sizes":[1,2,3,4]},"time":{"min":15,"max":25,"prep":5,"clean":5},"mess":"low","spaces":["table"],"offline":true},"learn":{"primary":"logical_thinking","secondary":["biology_nature","mathematics"],"goal":"Create a useful rule for sorting seeds, test it, and explain exceptions.","method":"classification-rule","skills":["biology_nature","mathematics"],"concepts":["classification-rule"]},"flow":"adult-guided","materials":["seeds","cups"],"steps":["safety-2","step-2"],"safety":{"level":"A","adultLed":true},"adaptations":["ACT-0002-ADAPT-LESS"],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null),
  ('ACT-0003@1.0.0', 'ACT-0003', '1.0.0', 'draft', 'synthetic-demo', 'sha256:677f8675b20af4eadd8abfe2d0aab2dad744f80ce65dcddeaf32e8150ed11ff8', '{"activityId":"ACT-0003","activityVersionId":"ACT-0003@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":8,"ageMax":10,"participantsMin":1,"participantsMax":3,"minutes":30,"safetyLevel":"C","mess":"low"},"locales":{"en-US":{"title":"Conductivity Tester","summary":"Compare approved objects in an adult-controlled, low-voltage circuit.","blocks":[{"id":"safety-3","type":"safety_notice","required":true,"payload":{"title":"Adult-controlled electrical setup","text":"Only the approved low-voltage holder and components may be used. Never connect to an outlet. The adult inspects before energizing."}},{"id":"step-3","type":"instruction","required":true,"payload":{"eyebrow":"Predict","title":"Choose approved test objects","text":"Predict which dry, approved objects will complete the circuit. The adult connects power only after inspection."}}]},"es-US":{"title":"Probador de conductividad","summary":"Comparen objetos aprobados en un circuito de bajo voltaje controlado por un adulto.","blocks":[{"id":"safety-3","type":"safety_notice","required":true,"payload":{"title":"Circuito bajo control adulto","text":"Usen solo el portapilas y componentes aprobados. Nunca conecten a un enchufe. El adulto inspecciona antes de energizar."}},{"id":"step-3","type":"instruction","required":true,"payload":{"eyebrow":"Predecir","title":"Elijan objetos aprobados","text":"Predigan qué objetos secos y aprobados completarán el circuito. El adulto conecta la energía después de inspeccionar."}}]}},"adaptations":[],"ragChunks":{"en-US":[{"id":"ACT-0003-en","label":"Conductivity Tester · safety","content":"Stop if any wire is hot, damaged, wet, or if a component is not on the approved list. Disconnect the battery before changing test objects."}],"es-US":[{"id":"ACT-0003-es","label":"Probador de conductividad · seguridad","content":"Detengan la actividad si un cable está caliente, dañado o mojado, o si un componente no está aprobado. Desconecten la batería antes de cambiar objetos."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0003","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[8,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":3,"sizes":[1,2,3]},"time":{"min":20,"max":30,"prep":5,"clean":5},"mess":"low","spaces":["table"],"offline":true},"learn":{"primary":"electricity","secondary":["physics","engineering"],"goal":"Compare approved objects in an adult-controlled, low-voltage circuit.","method":"closed-circuit-test","skills":["physics","engineering"],"concepts":["closed-circuit-test"]},"flow":"adult-guided","materials":["battery","led","wires","household-objects"],"steps":["safety-3","step-3"],"safety":{"level":"C","adultLed":true},"adaptations":[],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'C', null),
  ('ACT-0004@1.0.0', 'ACT-0004', '1.0.0', 'draft', 'synthetic-demo', 'sha256:42539085c75ce7ecf7d2d378ba89d5febd579d25e7ded55b7960e9b4badab096', '{"activityId":"ACT-0004","activityVersionId":"ACT-0004@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":7,"ageMax":10,"participantsMin":1,"participantsMax":3,"minutes":25,"safetyLevel":"B","mess":"low"},"locales":{"en-US":{"title":"CD and Balloon Hovercraft","summary":"Investigate how escaping air changes friction.","blocks":[{"id":"safety-4","type":"safety_notice","required":true,"payload":{"title":"Balloon control","text":"An adult inflates and checks the balloon. Discard broken balloon pieces immediately; do not use with latex allergy."}},{"id":"step-4","type":"instruction","required":true,"payload":{"eyebrow":"Test","title":"Compare air on and off","text":"Slide the device without airflow, then release the approved valve and compare the motion."}}]},"es-US":{"title":"Aerodeslizador con CD y globo","summary":"Investiguen cómo el aire que escapa cambia la fricción.","blocks":[{"id":"safety-4","type":"safety_notice","required":true,"payload":{"title":"Control del globo","text":"Un adulto infla y revisa el globo. Desechen de inmediato las piezas rotas; no usar con alergia al látex."}},{"id":"step-4","type":"instruction","required":true,"payload":{"eyebrow":"Probar","title":"Comparen con y sin aire","text":"Deslicen el dispositivo sin flujo de aire y después abran la válvula aprobada para comparar el movimiento."}}]}},"adaptations":[],"ragChunks":{"en-US":[{"id":"ACT-0004-en","label":"Hovercraft · troubleshooting","content":"If it does not glide, verify the surface is smooth, the opening is centered, and air can escape. Stop if the balloon tears."}],"es-US":[{"id":"ACT-0004-es","label":"Aerodeslizador · solución","content":"Si no se desliza, comprueben que la superficie sea lisa, la abertura esté centrada y el aire pueda salir. Deténganse si el globo se rompe."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0004","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[7,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":3,"sizes":[1,2,3]},"time":{"min":15,"max":25,"prep":5,"clean":5},"mess":"low","spaces":["floor","table"],"offline":true},"learn":{"primary":"physics","secondary":["engineering"],"goal":"Investigate how escaping air changes friction.","method":"air-cushion-friction","skills":["engineering"],"concepts":["air-cushion-friction"]},"flow":"adult-guided","materials":["balloon","disc","cap"],"steps":["safety-4","step-4"],"safety":{"level":"B","adultLed":true},"adaptations":[],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'B', null),
  ('ACT-0005@1.0.0', 'ACT-0005', '1.0.0', 'draft', 'synthetic-demo', 'sha256:695b4d4188877ca4d250764282c85605f1b2969e562e8ca7d6d329fbe62f3332', '{"activityId":"ACT-0005","activityVersionId":"ACT-0005@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":5,"ageMax":10,"participantsMin":1,"participantsMax":4,"minutes":25,"safetyLevel":"A","mess":"medium"},"locales":{"en-US":{"title":"Water Transporter","summary":"Design a way to move water while measuring spills and success.","blocks":[{"id":"safety-5","type":"safety_notice","required":true,"payload":{"title":"Prepare for spills","text":"Use a stable work area away from electricity. Wipe spills promptly to prevent slipping."}},{"id":"step-5","type":"instruction","required":true,"payload":{"eyebrow":"Design","title":"Move one cup of water","text":"Choose approved containers or channels, make one attempt, and measure what arrives."}}]},"es-US":{"title":"Transportador de agua","summary":"Diseñen una forma de mover agua midiendo derrames y resultados.","blocks":[{"id":"safety-5","type":"safety_notice","required":true,"payload":{"title":"Prepárense para derrames","text":"Usen una superficie estable lejos de electricidad. Sequen pronto los derrames para evitar resbalones."}},{"id":"step-5","type":"instruction","required":true,"payload":{"eyebrow":"Diseñar","title":"Muevan una taza de agua","text":"Elijan recipientes o canales aprobados, hagan un intento y midan cuánto llegó."}}]}},"adaptations":[{"id":"ACT-0005-ADAPT-LESS-MESS","summary":{"en-US":"Use a tray and half the water","es-US":"Usar una bandeja y la mitad del agua"},"visibleChanges":{"en-US":["Half-cup trial inside a tray"],"es-US":["Prueba de media taza dentro de una bandeja"]},"blocks":{"en-US":[{"id":"safety-5","type":"safety_notice","required":true,"payload":{"title":"Contain water","text":"Keep the full test inside a stable tray away from electricity."}},{"id":"step-5a","type":"instruction","required":true,"payload":{"eyebrow":"Low-mess version","title":"Move half a cup","text":"Run one half-cup trial in the tray and measure what arrives."}}],"es-US":[{"id":"safety-5","type":"safety_notice","required":true,"payload":{"title":"Contengan el agua","text":"Realicen toda la prueba dentro de una bandeja estable lejos de electricidad."}},{"id":"step-5a","type":"instruction","required":true,"payload":{"eyebrow":"Versión con menos desorden","title":"Muevan media taza","text":"Hagan una prueba de media taza en la bandeja y midan cuánto llegó."}}]}}],"ragChunks":{"en-US":[{"id":"ACT-0005-en","label":"Water Transporter · troubleshooting","content":"If little water arrives, inspect one connection at a time inside the tray. Do not add pressure or unapproved tubing."}],"es-US":[{"id":"ACT-0005-es","label":"Transportador de agua · solución","content":"Si llega poca agua, revisen una unión por vez dentro de la bandeja. No añadan presión ni tubos no aprobados."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0005","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[5,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":4,"sizes":[1,2,3,4]},"time":{"min":15,"max":25,"prep":5,"clean":5},"mess":"medium","spaces":["table","kitchen"],"offline":true},"learn":{"primary":"practical_life","secondary":["motor_skills","physics"],"goal":"Design a way to move water while measuring spills and success.","method":"volume-transfer","skills":["motor_skills","physics"],"concepts":["volume-transfer"]},"flow":"adult-guided","materials":["water","cups","sponge","tray"],"steps":["safety-5","step-5"],"safety":{"level":"A","adultLed":true},"adaptations":["ACT-0005-ADAPT-LESS-MESS"],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null),
  ('ACT-0006@1.0.0', 'ACT-0006', '1.0.0', 'draft', 'synthetic-demo', 'sha256:f85a5ee5307fc3b37022c14617bf05a2e96750377bcff2f801f7f06a811297aa', '{"activityId":"ACT-0006","activityVersionId":"ACT-0006@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":5,"ageMax":10,"participantsMin":1,"participantsMax":4,"minutes":25,"safetyLevel":"A","mess":"low"},"locales":{"en-US":{"title":"Tower with a Material Limit","summary":"Build the tallest stable tower using a fixed quantity of materials.","blocks":[{"id":"safety-6","type":"safety_notice","required":true,"payload":{"title":"Build below shoulder height","text":"Use lightweight approved materials on the floor or a stable table."}},{"id":"step-6","type":"instruction","required":true,"payload":{"eyebrow":"Build","title":"Use exactly twelve pieces","text":"Plan, build, measure, and improve without adding pieces."}}]},"es-US":{"title":"Torre con límite de materiales","summary":"Construyan la torre estable más alta usando una cantidad fija de materiales.","blocks":[{"id":"safety-6","type":"safety_notice","required":true,"payload":{"title":"Construyan bajo los hombros","text":"Usen materiales livianos aprobados en el piso o una mesa estable."}},{"id":"step-6","type":"instruction","required":true,"payload":{"eyebrow":"Construir","title":"Usen exactamente doce piezas","text":"Planeen, construyan, midan y mejoren sin añadir piezas."}}]}},"adaptations":[],"ragChunks":{"en-US":[{"id":"ACT-0006-en","label":"Limited Tower · guidance","content":"If the tower falls, keep the same twelve pieces and compare base width, symmetry, and the location of heavier pieces."}],"es-US":[{"id":"ACT-0006-es","label":"Torre limitada · guía","content":"Si la torre cae, mantengan las mismas doce piezas y comparen el ancho de la base, la simetría y la posición de las piezas pesadas."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0006","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[5,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":4,"sizes":[1,2,3,4]},"time":{"min":15,"max":25,"prep":5,"clean":5},"mess":"low","spaces":["floor","table"],"offline":true},"learn":{"primary":"creativity","secondary":["engineering","mathematics"],"goal":"Build the tallest stable tower using a fixed quantity of materials.","method":"constraint-building","skills":["engineering","mathematics"],"concepts":["constraint-building"]},"flow":"adult-guided","materials":["cardboard","tape"],"steps":["safety-6","step-6"],"safety":{"level":"A","adultLed":true},"adaptations":[],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null),
  ('ACT-0007@1.0.0', 'ACT-0007', '1.0.0', 'draft', 'synthetic-demo', 'sha256:9b9404f561cd6c72ac1a553c267d8ad4b242609c96bc4e43683712a2c03e4f80', '{"activityId":"ACT-0007","activityVersionId":"ACT-0007@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":6,"ageMax":10,"participantsMin":1,"participantsMax":3,"minutes":20,"safetyLevel":"A","mess":"low"},"locales":{"en-US":{"title":"Static Electricity Message","summary":"Use static charge to move lightweight pieces and reveal a pattern.","blocks":[{"id":"safety-7","type":"safety_notice","required":true,"payload":{"title":"Keep away from electronics","text":"Use only approved lightweight paper pieces. Keep balloons and charged objects away from outlets and electronics."}},{"id":"step-7","type":"instruction","required":true,"payload":{"eyebrow":"Reveal","title":"Charge, hover, observe","text":"Rub the approved object on cloth, hover above the pieces, and record which move."}}]},"es-US":{"title":"Mensaje de electricidad estática","summary":"Usen carga estática para mover piezas livianas y revelar un patrón.","blocks":[{"id":"safety-7","type":"safety_notice","required":true,"payload":{"title":"Lejos de aparatos electrónicos","text":"Usen solo piezas livianas de papel aprobadas. Mantengan los objetos cargados lejos de enchufes y aparatos."}},{"id":"step-7","type":"instruction","required":true,"payload":{"eyebrow":"Revelar","title":"Carguen, acerquen y observen","text":"Froten el objeto aprobado con tela, acérquenlo a las piezas y registren cuáles se mueven."}}]}},"adaptations":[],"ragChunks":{"en-US":[{"id":"ACT-0007-en","label":"Static Message · troubleshooting","content":"Static charge works best with dry materials. Repeat the same number of rubs and hold the charged object close without touching."}],"es-US":[{"id":"ACT-0007-es","label":"Mensaje estático · solución","content":"La carga estática funciona mejor con materiales secos. Repitan el mismo número de frotamientos y acerquen el objeto sin tocar."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0007","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[6,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":3,"sizes":[1,2,3]},"time":{"min":10,"max":20,"prep":5,"clean":5},"mess":"low","spaces":["table"],"offline":true},"learn":{"primary":"electricity","secondary":["physics","communication"],"goal":"Use static charge to move lightweight pieces and reveal a pattern.","method":"static-charge-signal","skills":["physics","communication"],"concepts":["static-charge-signal"]},"flow":"adult-guided","materials":["balloon","paper"],"steps":["safety-7","step-7"],"safety":{"level":"A","adultLed":true},"adaptations":[],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null),
  ('ACT-0008@1.0.0', 'ACT-0008', '1.0.0', 'draft', 'synthetic-demo', 'sha256:66cde3445dc5b15d553aacc29b45ca8378f2f7cbe105a97cdf26d34cad1ad773', '{"activityId":"ACT-0008","activityVersionId":"ACT-0008@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":5,"ageMax":10,"participantsMin":1,"participantsMax":4,"minutes":30,"safetyLevel":"A","mess":"medium"},"locales":{"en-US":{"title":"Cargo Ship","summary":"Build a foil boat and improve the load it carries without sinking.","blocks":[{"id":"safety-8","type":"safety_notice","required":true,"payload":{"title":"Water and small pieces","text":"Use a shallow tray away from electricity. Keep counters away from mouths and wipe spills."}},{"id":"step-8","type":"instruction","required":true,"payload":{"eyebrow":"Float","title":"Test an empty hull","text":"Shape one foil sheet, float it, then add equal counters one at a time."}}]},"es-US":{"title":"Barco de carga","summary":"Construyan un barco de aluminio y mejoren la carga que soporta sin hundirse.","blocks":[{"id":"safety-8","type":"safety_notice","required":true,"payload":{"title":"Agua y piezas pequeñas","text":"Usen una bandeja poco profunda lejos de electricidad. Mantengan las fichas lejos de la boca y sequen derrames."}},{"id":"step-8","type":"instruction","required":true,"payload":{"eyebrow":"Flotar","title":"Prueben un casco vacío","text":"Den forma a una hoja de aluminio, háganla flotar y añadan fichas iguales una por vez."}}]}},"adaptations":[],"ragChunks":{"en-US":[{"id":"ACT-0008-en","label":"Cargo Ship · troubleshooting","content":"If the boat sinks immediately, inspect for tears and test the empty hull. Spread equal counters across the base rather than stacking them."}],"es-US":[{"id":"ACT-0008-es","label":"Barco de carga · solución","content":"Si el barco se hunde de inmediato, revisen si hay roturas y prueben el casco vacío. Distribuyan fichas iguales sobre la base."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0008","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[5,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":4,"sizes":[1,2,3,4]},"time":{"min":20,"max":30,"prep":5,"clean":5},"mess":"medium","spaces":["table","kitchen"],"offline":true},"learn":{"primary":"engineering","secondary":["physics","mathematics"],"goal":"Build a foil boat and improve the load it carries without sinking.","method":"buoyancy-load","skills":["physics","mathematics"],"concepts":["buoyancy-load"]},"flow":"adult-guided","materials":["foil","water","coins","tray"],"steps":["safety-8","step-8"],"safety":{"level":"A","adultLed":true},"adaptations":[],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null),
  ('ACT-0009@1.0.0', 'ACT-0009', '1.0.0', 'draft', 'synthetic-demo', 'sha256:288fc37f46cca653cdfb957637c30f3947d71bf0f902071a62c9300a14580b1e', '{"activityId":"ACT-0009","activityVersionId":"ACT-0009@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":7,"ageMax":10,"participantsMin":1,"participantsMax":3,"minutes":30,"safetyLevel":"B","mess":"low"},"locales":{"en-US":{"title":"Cardboard Pulley","summary":"Build a guided wheel system and compare pulling direction and effort.","blocks":[{"id":"safety-9","type":"safety_notice","required":true,"payload":{"title":"Adult assembly check","text":"The adult handles cutting and attachment. Use only lightweight loads and keep cord away from necks and fingers."}},{"id":"step-9","type":"instruction","required":true,"payload":{"eyebrow":"Lift","title":"Test one lightweight load","text":"The adult checks the assembly. Pull slowly and observe direction before comparing configurations."}}]},"es-US":{"title":"Polea de cartón","summary":"Construyan un sistema de rueda guiada y comparen dirección y esfuerzo al tirar.","blocks":[{"id":"safety-9","type":"safety_notice","required":true,"payload":{"title":"Revisión adulta del montaje","text":"El adulto corta y fija las piezas. Usen cargas livianas y mantengan el cordón lejos del cuello y los dedos."}},{"id":"step-9","type":"instruction","required":true,"payload":{"eyebrow":"Elevar","title":"Prueben una carga liviana","text":"El adulto revisa el montaje. Tiren lentamente y observen la dirección antes de comparar configuraciones."}}]}},"adaptations":[],"ragChunks":{"en-US":[{"id":"ACT-0009-en","label":"Cardboard Pulley · troubleshooting","content":"If the wheel does not turn, stop pulling and inspect alignment with no load. Do not increase the load or wrap cord around a hand."}],"es-US":[{"id":"ACT-0009-es","label":"Polea de cartón · solución","content":"Si la rueda no gira, dejen de tirar y revisen la alineación sin carga. No aumenten el peso ni enrollen el cordón en la mano."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0009","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[7,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":3,"sizes":[1,2,3]},"time":{"min":20,"max":30,"prep":5,"clean":5},"mess":"low","spaces":["table"],"offline":true},"learn":{"primary":"physics","secondary":["engineering","motor_skills"],"goal":"Build a guided wheel system and compare pulling direction and effort.","method":"pulley-force","skills":["engineering","motor_skills"],"concepts":["pulley-force"]},"flow":"adult-guided","materials":["cardboard","string","cup"],"steps":["safety-9","step-9"],"safety":{"level":"B","adultLed":true},"adaptations":[],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'B', null),
  ('ACT-0010@1.0.0', 'ACT-0010', '1.0.0', 'draft', 'synthetic-demo', 'sha256:48e431fffb359c34086f2be76ed220ced632e2b10589b3c81830aad173ffbfe9', '{"activityId":"ACT-0010","activityVersionId":"ACT-0010@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":5,"ageMax":10,"participantsMin":1,"participantsMax":4,"minutes":20,"safetyLevel":"A","mess":"low"},"locales":{"en-US":{"title":"Germination Comparison","summary":"Compare how one controlled condition affects seed germination over several days.","blocks":[{"id":"safety-10","type":"safety_notice","required":true,"payload":{"title":"Observe, do not eat","text":"Use the seeds only for observation. Wash hands after handling and discard any moldy sample sealed."}},{"id":"step-10","type":"instruction","required":true,"payload":{"eyebrow":"Set up","title":"Change one condition","text":"Prepare two labeled samples that differ in one approved condition and record daily observations."}}]},"es-US":{"title":"Comparación de germinación","summary":"Comparen cómo una condición controlada afecta la germinación durante varios días.","blocks":[{"id":"safety-10","type":"safety_notice","required":true,"payload":{"title":"Observar, no comer","text":"Usen las semillas solo para observar. Lávense las manos y desechen sellada cualquier muestra con moho."}},{"id":"step-10","type":"instruction","required":true,"payload":{"eyebrow":"Preparar","title":"Cambien una condición","text":"Preparen dos muestras etiquetadas que difieran en una condición aprobada y registren observaciones diarias."}}]}},"adaptations":[],"ragChunks":{"en-US":[{"id":"ACT-0010-en","label":"Germination · troubleshooting","content":"If no change appears, verify moisture without flooding, labels, and elapsed days. Do not open or smell a moldy sample; seal and discard it."}],"es-US":[{"id":"ACT-0010-es","label":"Germinación · solución","content":"Si no hay cambios, revisen la humedad sin inundar, las etiquetas y los días transcurridos. No abran ni huelan una muestra con moho; séllenla y deséchenla."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0010","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[5,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":4,"sizes":[1,2,3,4]},"time":{"min":10,"max":20,"prep":5,"clean":5},"mess":"low","spaces":["table","window"],"offline":true},"learn":{"primary":"biology_nature","secondary":["logical_thinking","self_regulation"],"goal":"Compare how one controlled condition affects seed germination over several days.","method":"controlled-comparison","skills":["logical_thinking","self_regulation"],"concepts":["controlled-comparison"]},"flow":"adult-guided","materials":["seeds","paper-towel","water","bags"],"steps":["safety-10","step-10"],"safety":{"level":"A","adultLed":true},"adaptations":[],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null),
  ('ACT-0011@1.0.0', 'ACT-0011', '1.0.0', 'draft', 'synthetic-demo', 'sha256:5d604cfff628844038751254906e5de200fb4385c9fb2f428071d8e36ee77329', '{"activityId":"ACT-0011","activityVersionId":"ACT-0011@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":5,"ageMax":10,"participantsMin":1,"participantsMax":4,"minutes":25,"safetyLevel":"A","mess":"low"},"locales":{"en-US":{"title":"Dissolving Detective","summary":"Compare how approved household solids behave in room-temperature water using the same test each time.","blocks":[{"id":"safety-11","type":"safety_notice","required":true,"payload":{"title":"Observe, do not taste","text":"Use only the labeled test materials and room-temperature water. Do not taste samples; wipe spills and wash hands afterward."}},{"id":"step-11","type":"instruction","required":true,"payload":{"eyebrow":"Compare · 10 min","title":"Run the same test three times","text":"Add the same amount of water to three clear cups, add one labeled solid to each, stir the same number of times, and record what remains visible."}},{"id":"question-11","type":"question","required":false,"payload":{"prompt":"Which evidence shows that disappearing from view is not the same as no longer existing?"}}]},"es-US":{"title":"Detectives de disolución","summary":"Comparen cómo se comportan sólidos domésticos aprobados en agua a temperatura ambiente usando siempre la misma prueba.","blocks":[{"id":"safety-11","type":"safety_notice","required":true,"payload":{"title":"Observar, no probar","text":"Usen solo los materiales etiquetados y agua a temperatura ambiente. No prueben las muestras; sequen derrames y lávense las manos."}},{"id":"step-11","type":"instruction","required":true,"payload":{"eyebrow":"Comparar · 10 min","title":"Repitan la misma prueba tres veces","text":"Pongan igual cantidad de agua en tres vasos transparentes, agreguen un sólido etiquetado a cada uno, mezclen el mismo número de veces y registren qué queda visible."}},{"id":"question-11","type":"question","required":false,"payload":{"prompt":"¿Qué evidencia muestra que dejar de verse no significa dejar de existir?"}}]}},"adaptations":[{"id":"ACT-0011-ADAPT-TWO","summary":{"en-US":"Compare two materials","es-US":"Comparar dos materiales"},"visibleChanges":{"en-US":["Use two labeled cups while preserving equal amounts and stirring"],"es-US":["Usar dos vasos etiquetados conservando cantidades y mezcla iguales"]},"blocks":{"en-US":[{"id":"safety-11","type":"safety_notice","required":true,"payload":{"title":"Observe, do not taste","text":"Use room-temperature water and do not taste the samples."}},{"id":"step-11a","type":"instruction","required":true,"payload":{"eyebrow":"Short comparison","title":"Test two materials","text":"Use equal water and equal stirring to compare two labeled solids."}}],"es-US":[{"id":"safety-11","type":"safety_notice","required":true,"payload":{"title":"Observar, no probar","text":"Usen agua a temperatura ambiente y no prueben las muestras."}},{"id":"step-11a","type":"instruction","required":true,"payload":{"eyebrow":"Comparación corta","title":"Prueben dos materiales","text":"Usen igual cantidad de agua y de mezcla para comparar dos sólidos etiquetados."}}]}}],"ragChunks":{"en-US":[{"id":"ACT-0011-en","label":"Dissolving Detective · guidance","content":"If comparisons are unclear, confirm equal water, equal solid amounts, equal stirring and readable labels. Do not heat or taste any sample."}],"es-US":[{"id":"ACT-0011-es","label":"Detectives de disolución · guía","content":"Si la comparación no es clara, comprueben que haya igual cantidad de agua y sólido, igual mezcla y etiquetas legibles. No calienten ni prueben las muestras."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0011","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[5,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":4,"sizes":[1,2,3,4]},"time":{"min":15,"max":25,"prep":5,"clean":5},"mess":"low","spaces":["table","kitchen"],"offline":true},"learn":{"primary":"safe_chemistry","secondary":["mathematics","logical_thinking"],"goal":"Compare how approved household solids behave in room-temperature water using the same test each time.","method":"controlled-dissolving-comparison","skills":["mathematics","logical_thinking"],"concepts":["controlled-dissolving-comparison"]},"flow":"adult-guided","materials":["clear-cups","water","salt","sugar","sand","spoons"],"steps":["safety-11","step-11","question-11"],"safety":{"level":"A","adultLed":true},"adaptations":["ACT-0011-ADAPT-TWO"],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null),
  ('ACT-0012@1.0.0', 'ACT-0012', '1.0.0', 'draft', 'synthetic-demo', 'sha256:8bd1cf5d19a069ca46a05fc39ee0f27edd2882703503cc8e5e96f9f45b262152', '{"activityId":"ACT-0012","activityVersionId":"ACT-0012@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":5,"ageMax":10,"participantsMin":2,"participantsMax":4,"minutes":20,"safetyLevel":"A","mess":"low"},"locales":{"en-US":{"title":"Build It From My Words","summary":"Practice precise communication by describing a small block arrangement another person cannot see.","blocks":[{"id":"safety-12","type":"safety_notice","required":true,"payload":{"title":"Use safe building pieces","text":"Use large, lightweight pieces on a stable surface and keep the visual divider below face height."}},{"id":"step-12","type":"instruction","required":true,"payload":{"eyebrow":"Describe · 8 min","title":"Give clues without showing","text":"One person builds a five-piece arrangement behind the divider and describes it while a partner builds a match. Switch roles after comparing."}},{"id":"question-12","type":"question","required":false,"payload":{"prompt":"Which words made position, direction, or order easiest to understand?"}}]},"es-US":{"title":"Constrúyelo con mis palabras","summary":"Practiquen comunicación precisa describiendo una construcción pequeña que otra persona no puede ver.","blocks":[{"id":"safety-12","type":"safety_notice","required":true,"payload":{"title":"Usen piezas seguras","text":"Usen piezas grandes y livianas sobre una superficie estable y mantengan el separador visual por debajo de la cara."}},{"id":"step-12","type":"instruction","required":true,"payload":{"eyebrow":"Describir · 8 min","title":"Den pistas sin mostrar","text":"Una persona arma una construcción de cinco piezas detrás del separador y la describe mientras otra intenta copiarla. Cambien roles después de comparar."}},{"id":"question-12","type":"question","required":false,"payload":{"prompt":"¿Qué palabras ayudaron más a entender la posición, la dirección o el orden?"}}]}},"adaptations":[],"ragChunks":{"en-US":[{"id":"ACT-0012-en","label":"Build It From My Words · guidance","content":"If the designs differ, compare one position at a time and replace vague words with an observable relation such as above, beside, touching, or turned."}],"es-US":[{"id":"ACT-0012-es","label":"Constrúyelo con mis palabras · guía","content":"Si los diseños son distintos, comparen una posición por vez y sustituyan palabras vagas por relaciones observables como arriba, al lado, tocando o girado."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0012","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[5,10],"levels":["L1","L2","L3","L4"],"group":{"min":2,"max":4,"sizes":[2,3,4]},"time":{"min":10,"max":20,"prep":5,"clean":5},"mess":"low","spaces":["floor","table"],"offline":true},"learn":{"primary":"communication","secondary":["logical_thinking","self_regulation","motor_skills"],"goal":"Practice precise communication by describing a small block arrangement another person cannot see.","method":"hidden-model-description","skills":["logical_thinking","self_regulation","motor_skills"],"concepts":["hidden-model-description"]},"flow":"adult-guided","materials":["large-blocks","cardboard-divider"],"steps":["safety-12","step-12","question-12"],"safety":{"level":"A","adultLed":true},"adaptations":[],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null),
  ('ACT-0013@1.0.0', 'ACT-0013', '1.0.0', 'draft', 'synthetic-demo', 'sha256:8d84cb07201655bbc0c5f53b2fa9f3f813c59b51f9359d0d31a416bc4fc832b0', '{"activityId":"ACT-0013","activityVersionId":"ACT-0013@1.0.0","status":"published","releaseChannel":"synthetic-demo","eligibility":{"ageMin":5,"ageMax":10,"participantsMin":1,"participantsMax":4,"minutes":15,"safetyLevel":"A","mess":"low"},"locales":{"en-US":{"title":"Balance Path Designer","summary":"Design, test, and revise a floor-level movement path with clear rules and observations.","blocks":[{"id":"safety-13","type":"safety_notice","required":true,"payload":{"title":"Stay at floor level","text":"Clear the area, use only flat floor markers, walk rather than jump, and stop if the surface slips."}},{"id":"step-13","type":"instruction","required":true,"payload":{"eyebrow":"Design · 7 min","title":"Make a three-part path","text":"Place a start, two direction changes, and a finish. Walk it once, name where balance was hardest, and change one marker."}},{"id":"question-13","type":"question","required":false,"payload":{"prompt":"Which change made the path easier to control, and what did you observe?"}}]},"es-US":{"title":"Diseñadores de caminos de equilibrio","summary":"Diseñen, prueben y revisen un recorrido de movimiento a nivel del suelo con reglas y observaciones claras.","blocks":[{"id":"safety-13","type":"safety_notice","required":true,"payload":{"title":"Siempre a nivel del suelo","text":"Despejen el área, usen solo marcas planas, caminen sin saltar y deténganse si la superficie resbala."}},{"id":"step-13","type":"instruction","required":true,"payload":{"eyebrow":"Diseñar · 7 min","title":"Creen un camino de tres partes","text":"Marquen inicio, dos cambios de dirección y final. Recórranlo una vez, nombren dónde costó más mantener el equilibrio y cambien una marca."}},{"id":"question-13","type":"question","required":false,"payload":{"prompt":"¿Qué cambio hizo el camino más fácil de controlar y qué observaron?"}}]}},"adaptations":[],"ragChunks":{"en-US":[{"id":"ACT-0013-en","label":"Balance Path · guidance","content":"If the path feels unsafe, stop, remove loose or raised markers, widen turns, and walk slowly on a clear nonslip floor."}],"es-US":[{"id":"ACT-0013-es","label":"Camino de equilibrio · guía","content":"Si el recorrido no se siente seguro, deténganse, quiten marcas sueltas o elevadas, amplíen los giros y caminen despacio sobre un piso despejado y estable."}]},"evaluationNotice":"Synthetic content for technical evaluation; no human publication gate is claimed."}'::jsonb, 'activity@2', 'en-US', '{"schema":"activity@2","id":"ACT-0013","version":"1.0.0","sourceLocale":"en-US","fit":{"age":[5,10],"levels":["L1","L2","L3","L4"],"group":{"min":1,"max":4,"sizes":[1,2,3,4]},"time":{"min":10,"max":15,"prep":5,"clean":5},"mess":"low","spaces":["floor"],"offline":true},"learn":{"primary":"motor_skills","secondary":["self_regulation","engineering"],"goal":"Design, test, and revise a floor-level movement path with clear rules and observations.","method":"floor-path-balance-revision","skills":["self_regulation","engineering"],"concepts":["floor-path-balance-revision"]},"flow":"adult-guided","materials":["flat-floor-markers"],"steps":["safety-13","step-13","question-13"],"safety":{"level":"A","adultLed":true},"adaptations":[],"closeout":{"mode":"observation","maxSeconds":20}}'::jsonb, 'A', null)
