  ('ACT-0011@1.0.0', 'es-US', '{"schema":"activity-locale@2","activityVersionId":"ACT-0011@1.0.0","locale":"es-US","content":{"title":"Detectives de disolución","summary":"Comparen cómo se comportan sólidos domésticos aprobados en agua a temperatura ambiente usando siempre la misma prueba."},"evaluationNotice":"synthetic-not-human-reviewed"}'::jsonb, 'sha256:1a8e022e8486ff4f858a9dde4d968b17b2d4a747f30e62d5a4cff13f6074d96a', 'synthetic', null, null),
