insert into public.kids_activity_block_v2 (activity_version_id, locale, block_id, kind, block_version, required, position, data) values
  ('ACT-0001@1.0.0', 'en-US', 'safety-1', 'safety_notice', 1, true, 1, '{"title":"Adult check","text":"Keep hands and faces away from beneath the bridge. The adult positions the supports and cup."}'::jsonb),
  ('ACT-0001@1.0.0', 'en-US', 'step-1', 'instruction', 1, true, 2, '{"eyebrow":"Discover · 6 min","title":"Test a flat sheet first","text":"Place one sheet across two supports. Center the empty cup, add one crayon at a time, and record the last stable load."}'::jsonb),
  ('ACT-0001@1.0.0', 'en-US', 'question-1', 'question', 1, false, 3, '{"prompt":"What changed in the paper just before the bridge failed?"}'::jsonb),
  ('ACT-0001@1.0.0', 'es-US', 'safety-1', 'safety_notice', 1, true, 1, '{"title":"Revisión adulta","text":"Mantengan manos y caras lejos de la zona bajo el puente. El adulto coloca los apoyos y el vaso."}'::jsonb),
  ('ACT-0001@1.0.0', 'es-US', 'step-1', 'instruction', 1, true, 2, '{"eyebrow":"Descubrir · 6 min","title":"Prueben primero una hoja plana","text":"Coloca una hoja entre dos apoyos. Centra el vaso vacío, añade un crayón por turno y registra la última carga estable."}'::jsonb),
  ('ACT-0001@1.0.0', 'es-US', 'question-1', 'question', 1, false, 3, '{"prompt":"¿Qué cambió en el papel justo antes de que el puente cediera?"}'::jsonb),
  ('ACT-0002@1.0.0', 'en-US', 'safety-2', 'safety_notice', 1, true, 1, '{"title":"Not for eating","text":"Use clean, dry seeds as objects only. Keep small pieces away from mouths and younger children."}'::jsonb),
  ('ACT-0002@1.0.0', 'en-US', 'step-2', 'instruction', 1, true, 2, '{"eyebrow":"Sort · 8 min","title":"Choose one visible rule","text":"Sort the mixed seeds by one property, then ask someone else to infer your rule."}'::jsonb),
  ('ACT-0002@1.0.0', 'es-US', 'safety-2', 'safety_notice', 1, true, 1, '{"title":"No son alimento","text":"Usen semillas limpias y secas solo como objetos. Mantengan las piezas pequeñas lejos de bocas y niños menores."}'::jsonb),
  ('ACT-0002@1.0.0', 'es-US', 'step-2', 'instruction', 1, true, 2, '{"eyebrow":"Clasificar · 8 min","title":"Elijan una regla visible","text":"Clasifiquen las semillas por una propiedad y pidan a otra persona que deduzca la regla."}'::jsonb),
  ('ACT-0003@1.0.0', 'en-US', 'safety-3', 'safety_notice', 1, true, 1, '{"title":"Adult-controlled electrical setup","text":"Only the approved low-voltage holder and components may be used. Never connect to an outlet. The adult inspects before energizing."}'::jsonb),
  ('ACT-0003@1.0.0', 'en-US', 'step-3', 'instruction', 1, true, 2, '{"eyebrow":"Predict","title":"Choose approved test objects","text":"Predict which dry, approved objects will complete the circuit. The adult connects power only after inspection."}'::jsonb),
  ('ACT-0003@1.0.0', 'es-US', 'safety-3', 'safety_notice', 1, true, 1, '{"title":"Circuito bajo control adulto","text":"Usen solo el portapilas y componentes aprobados. Nunca conecten a un enchufe. El adulto inspecciona antes de energizar."}'::jsonb),
  ('ACT-0003@1.0.0', 'es-US', 'step-3', 'instruction', 1, true, 2, '{"eyebrow":"Predecir","title":"Elijan objetos aprobados","text":"Predigan qué objetos secos y aprobados completarán el circuito. El adulto conecta la energía después de inspeccionar."}'::jsonb),
  ('ACT-0004@1.0.0', 'en-US', 'safety-4', 'safety_notice', 1, true, 1, '{"title":"Balloon control","text":"An adult inflates and checks the balloon. Discard broken balloon pieces immediately; do not use with latex allergy."}'::jsonb),
  ('ACT-0004@1.0.0', 'en-US', 'step-4', 'instruction', 1, true, 2, '{"eyebrow":"Test","title":"Compare air on and off","text":"Slide the device without airflow, then release the approved valve and compare the motion."}'::jsonb),
  ('ACT-0004@1.0.0', 'es-US', 'safety-4', 'safety_notice', 1, true, 1, '{"title":"Control del globo","text":"Un adulto infla y revisa el globo. Desechen de inmediato las piezas rotas; no usar con alergia al látex."}'::jsonb),
  ('ACT-0004@1.0.0', 'es-US', 'step-4', 'instruction', 1, true, 2, '{"eyebrow":"Probar","title":"Comparen con y sin aire","text":"Deslicen el dispositivo sin flujo de aire y después abran la válvula aprobada para comparar el movimiento."}'::jsonb),
  ('ACT-0005@1.0.0', 'en-US', 'safety-5', 'safety_notice', 1, true, 1, '{"title":"Prepare for spills","text":"Use a stable work area away from electricity. Wipe spills promptly to prevent slipping."}'::jsonb),
  ('ACT-0005@1.0.0', 'en-US', 'step-5', 'instruction', 1, true, 2, '{"eyebrow":"Design","title":"Move one cup of water","text":"Choose approved containers or channels, make one attempt, and measure what arrives."}'::jsonb),
  ('ACT-0005@1.0.0', 'es-US', 'safety-5', 'safety_notice', 1, true, 1, '{"title":"Prepárense para derrames","text":"Usen una superficie estable lejos de electricidad. Sequen pronto los derrames para evitar resbalones."}'::jsonb),
  ('ACT-0005@1.0.0', 'es-US', 'step-5', 'instruction', 1, true, 2, '{"eyebrow":"Diseñar","title":"Muevan una taza de agua","text":"Elijan recipientes o canales aprobados, hagan un intento y midan cuánto llegó."}'::jsonb),
  ('ACT-0006@1.0.0', 'en-US', 'safety-6', 'safety_notice', 1, true, 1, '{"title":"Build below shoulder height","text":"Use lightweight approved materials on the floor or a stable table."}'::jsonb),
  ('ACT-0006@1.0.0', 'en-US', 'step-6', 'instruction', 1, true, 2, '{"eyebrow":"Build","title":"Use exactly twelve pieces","text":"Plan, build, measure, and improve without adding pieces."}'::jsonb),
  ('ACT-0006@1.0.0', 'es-US', 'safety-6', 'safety_notice', 1, true, 1, '{"title":"Construyan bajo los hombros","text":"Usen materiales livianos aprobados en el piso o una mesa estable."}'::jsonb),
  ('ACT-0006@1.0.0', 'es-US', 'step-6', 'instruction', 1, true, 2, '{"eyebrow":"Construir","title":"Usen exactamente doce piezas","text":"Planeen, construyan, midan y mejoren sin añadir piezas."}'::jsonb),
  ('ACT-0007@1.0.0', 'en-US', 'safety-7', 'safety_notice', 1, true, 1, '{"title":"Keep away from electronics","text":"Use only approved lightweight paper pieces. Keep balloons and charged objects away from outlets and electronics."}'::jsonb),
  ('ACT-0007@1.0.0', 'en-US', 'step-7', 'instruction', 1, true, 2, '{"eyebrow":"Reveal","title":"Charge, hover, observe","text":"Rub the approved object on cloth, hover above the pieces, and record which move."}'::jsonb),
  ('ACT-0007@1.0.0', 'es-US', 'safety-7', 'safety_notice', 1, true, 1, '{"title":"Lejos de aparatos electrónicos","text":"Usen solo piezas livianas de papel aprobadas. Mantengan los objetos cargados lejos de enchufes y aparatos."}'::jsonb),
  ('ACT-0007@1.0.0', 'es-US', 'step-7', 'instruction', 1, true, 2, '{"eyebrow":"Revelar","title":"Carguen, acerquen y observen","text":"Froten el objeto aprobado con tela, acérquenlo a las piezas y registren cuáles se mueven."}'::jsonb),
  ('ACT-0008@1.0.0', 'en-US', 'safety-8', 'safety_notice', 1, true, 1, '{"title":"Water and small pieces","text":"Use a shallow tray away from electricity. Keep counters away from mouths and wipe spills."}'::jsonb),
  ('ACT-0008@1.0.0', 'en-US', 'step-8', 'instruction', 1, true, 2, '{"eyebrow":"Float","title":"Test an empty hull","text":"Shape one foil sheet, float it, then add equal counters one at a time."}'::jsonb),
  ('ACT-0008@1.0.0', 'es-US', 'safety-8', 'safety_notice', 1, true, 1, '{"title":"Agua y piezas pequeñas","text":"Usen una bandeja poco profunda lejos de electricidad. Mantengan las fichas lejos de la boca y sequen derrames."}'::jsonb),
  ('ACT-0008@1.0.0', 'es-US', 'step-8', 'instruction', 1, true, 2, '{"eyebrow":"Flotar","title":"Prueben un casco vacío","text":"Den forma a una hoja de aluminio, háganla flotar y añadan fichas iguales una por vez."}'::jsonb),
  ('ACT-0009@1.0.0', 'en-US', 'safety-9', 'safety_notice', 1, true, 1, '{"title":"Adult assembly check","text":"The adult handles cutting and attachment. Use only lightweight loads and keep cord away from necks and fingers."}'::jsonb),
  ('ACT-0009@1.0.0', 'en-US', 'step-9', 'instruction', 1, true, 2, '{"eyebrow":"Lift","title":"Test one lightweight load","text":"The adult checks the assembly. Pull slowly and observe direction before comparing configurations."}'::jsonb),
  ('ACT-0009@1.0.0', 'es-US', 'safety-9', 'safety_notice', 1, true, 1, '{"title":"Revisión adulta del montaje","text":"El adulto corta y fija las piezas. Usen cargas livianas y mantengan el cordón lejos del cuello y los dedos."}'::jsonb),
  ('ACT-0009@1.0.0', 'es-US', 'step-9', 'instruction', 1, true, 2, '{"eyebrow":"Elevar","title":"Prueben una carga liviana","text":"El adulto revisa el montaje. Tiren lentamente y observen la dirección antes de comparar configuraciones."}'::jsonb),
  ('ACT-0010@1.0.0', 'en-US', 'safety-10', 'safety_notice', 1, true, 1, '{"title":"Observe, do not eat","text":"Use the seeds only for observation. Wash hands after handling and discard any moldy sample sealed."}'::jsonb),
  ('ACT-0010@1.0.0', 'en-US', 'step-10', 'instruction', 1, true, 2, '{"eyebrow":"Set up","title":"Change one condition","text":"Prepare two labeled samples that differ in one approved condition and record daily observations."}'::jsonb),
  ('ACT-0010@1.0.0', 'es-US', 'safety-10', 'safety_notice', 1, true, 1, '{"title":"Observar, no comer","text":"Usen las semillas solo para observar. Lávense las manos y desechen sellada cualquier muestra con moho."}'::jsonb),
  ('ACT-0010@1.0.0', 'es-US', 'step-10', 'instruction', 1, true, 2, '{"eyebrow":"Preparar","title":"Cambien una condición","text":"Preparen dos muestras etiquetadas que difieran en una condición aprobada y registren observaciones diarias."}'::jsonb),
  ('ACT-0011@1.0.0', 'en-US', 'safety-11', 'safety_notice', 1, true, 1, '{"title":"Observe, do not taste","text":"Use only the labeled test materials and room-temperature water. Do not taste samples; wipe spills and wash hands afterward."}'::jsonb),
  ('ACT-0011@1.0.0', 'en-US', 'step-11', 'instruction', 1, true, 2, '{"eyebrow":"Compare · 10 min","title":"Run the same test three times","text":"Add the same amount of water to three clear cups, add one labeled solid to each, stir the same number of times, and record what remains visible."}'::jsonb),
  ('ACT-0011@1.0.0', 'en-US', 'question-11', 'question', 1, false, 3, '{"prompt":"Which evidence shows that disappearing from view is not the same as no longer existing?"}'::jsonb),
  ('ACT-0011@1.0.0', 'es-US', 'safety-11', 'safety_notice', 1, true, 1, '{"title":"Observar, no probar","text":"Usen solo los materiales etiquetados y agua a temperatura ambiente. No prueben las muestras; sequen derrames y lávense las manos."}'::jsonb),
  ('ACT-0011@1.0.0', 'es-US', 'step-11', 'instruction', 1, true, 2, '{"eyebrow":"Comparar · 10 min","title":"Repitan la misma prueba tres veces","text":"Pongan igual cantidad de agua en tres vasos transparentes, agreguen un sólido etiquetado a cada uno, mezclen el mismo número de veces y registren qué queda visible."}'::jsonb),
  ('ACT-0011@1.0.0', 'es-US', 'question-11', 'question', 1, false, 3, '{"prompt":"¿Qué evidencia muestra que dejar de verse no significa dejar de existir?"}'::jsonb),
  ('ACT-0012@1.0.0', 'en-US', 'safety-12', 'safety_notice', 1, true, 1, '{"title":"Use safe building pieces","text":"Use large, lightweight pieces on a stable surface and keep the visual divider below face height."}'::jsonb),
  ('ACT-0012@1.0.0', 'en-US', 'step-12', 'instruction', 1, true, 2, '{"eyebrow":"Describe · 8 min","title":"Give clues without showing","text":"One person builds a five-piece arrangement behind the divider and describes it while a partner builds a match. Switch roles after comparing."}'::jsonb),
  ('ACT-0012@1.0.0', 'en-US', 'question-12', 'question', 1, false, 3, '{"prompt":"Which words made position, direction, or order easiest to understand?"}'::jsonb),
  ('ACT-0012@1.0.0', 'es-US', 'safety-12', 'safety_notice', 1, true, 1, '{"title":"Usen piezas seguras","text":"Usen piezas grandes y livianas sobre una superficie estable y mantengan el separador visual por debajo de la cara."}'::jsonb),
  ('ACT-0012@1.0.0', 'es-US', 'step-12', 'instruction', 1, true, 2, '{"eyebrow":"Describir · 8 min","title":"Den pistas sin mostrar","text":"Una persona arma una construcción de cinco piezas detrás del separador y la describe mientras otra intenta copiarla. Cambien roles después de comparar."}'::jsonb),
  ('ACT-0012@1.0.0', 'es-US', 'question-12', 'question', 1, false, 3, '{"prompt":"¿Qué palabras ayudaron más a entender la posición, la dirección o el orden?"}'::jsonb),
  ('ACT-0013@1.0.0', 'en-US', 'safety-13', 'safety_notice', 1, true, 1, '{"title":"Stay at floor level","text":"Clear the area, use only flat floor markers, walk rather than jump, and stop if the surface slips."}'::jsonb),
  ('ACT-0013@1.0.0', 'en-US', 'step-13', 'instruction', 1, true, 2, '{"eyebrow":"Design · 7 min","title":"Make a three-part path","text":"Place a start, two direction changes, and a finish. Walk it once, name where balance was hardest, and change one marker."}'::jsonb),
  ('ACT-0013@1.0.0', 'en-US', 'question-13', 'question', 1, false, 3, '{"prompt":"Which change made the path easier to control, and what did you observe?"}'::jsonb),
  ('ACT-0013@1.0.0', 'es-US', 'safety-13', 'safety_notice', 1, true, 1, '{"title":"Siempre a nivel del suelo","text":"Despejen el área, usen solo marcas planas, caminen sin saltar y deténganse si la superficie resbala."}'::jsonb),
  ('ACT-0013@1.0.0', 'es-US', 'step-13', 'instruction', 1, true, 2, '{"eyebrow":"Diseñar · 7 min","title":"Creen un camino de tres partes","text":"Marquen inicio, dos cambios de dirección y final. Recórranlo una vez, nombren dónde costó más mantener el equilibrio y cambien una marca."}'::jsonb),
  ('ACT-0013@1.0.0', 'es-US', 'question-13', 'question', 1, false, 3, '{"prompt":"¿Qué cambio hizo el camino más fácil de controlar y qué observaron?"}'::jsonb)
insert into public.kids_activity_adaptation (adaptation_id, activity_version_id, localized_content, safety_impact, requires_confirmation, approval_record) values
  ('ACT-0001-ADAPT-SHORT', 'ACT-0001@1.0.0', '{"en-US":{"summary":"Use one design cycle","visibleChanges":["Test one folded design after the baseline","Keep the same safety and comparison rules"],"blocks":[{"id":"safety-1","kind":"safety_notice","version":1,"required":true,"data":{"title":"Adult check","text":"Keep hands and faces away from beneath the bridge. The adult positions the supports and cup."}},{"id":"step-short","kind":"instruction","version":1,"required":true,"data":{"eyebrow":"Short version · 18 min","title":"Test one change","text":"Test the flat sheet, choose one fold, and compare both results with the same load."}}]},"es-US":{"summary":"Usar un solo ciclo de diseño","visibleChanges":["Probar un diseño plegado después de la referencia","Mantener las mismas reglas de seguridad y comparación"],"blocks":[{"id":"safety-1","kind":"safety_notice","version":1,"required":true,"data":{"title":"Revisión adulta","text":"Mantengan manos y caras lejos de la zona bajo el puente. El adulto coloca los apoyos y el vaso."}},{"id":"step-short","kind":"instruction","version":1,"required":true,"data":{"eyebrow":"Versión corta · 18 min","title":"Prueben un cambio","text":"Prueben la hoja plana, elijan un pliegue y comparen ambos resultados con la misma carga."}}]}}'::jsonb, 'none', true, '{"scope":"synthetic-evaluation","humanApprovalClaimed":false}'::jsonb),
  ('ACT-0002-ADAPT-LESS', 'ACT-0002@1.0.0', '{"en-US":{"summary":"Use two seed types","visibleChanges":["Reduce the number of categories"],"blocks":[{"id":"safety-2","kind":"safety_notice","version":1,"required":true,"data":{"title":"Not for eating","text":"Keep the dry seeds away from mouths."}},{"id":"step-2a","kind":"instruction","version":1,"required":true,"data":{"eyebrow":"Short version","title":"Compare two kinds","text":"Choose one visible difference and sort two seed types."}}]},"es-US":{"summary":"Usar dos tipos de semillas","visibleChanges":["Reducir el número de categorías"],"blocks":[{"id":"safety-2","kind":"safety_notice","version":1,"required":true,"data":{"title":"No son alimento","text":"Mantengan las semillas secas lejos de la boca."}},{"id":"step-2a","kind":"instruction","version":1,"required":true,"data":{"eyebrow":"Versión corta","title":"Comparen dos tipos","text":"Elijan una diferencia visible y clasifiquen dos tipos de semillas."}}]}}'::jsonb, 'none', true, '{"scope":"synthetic-evaluation","humanApprovalClaimed":false}'::jsonb),
  ('ACT-0005-ADAPT-LESS-MESS', 'ACT-0005@1.0.0', '{"en-US":{"summary":"Use a tray and half the water","visibleChanges":["Half-cup trial inside a tray"],"blocks":[{"id":"safety-5","kind":"safety_notice","version":1,"required":true,"data":{"title":"Contain water","text":"Keep the full test inside a stable tray away from electricity."}},{"id":"step-5a","kind":"instruction","version":1,"required":true,"data":{"eyebrow":"Low-mess version","title":"Move half a cup","text":"Run one half-cup trial in the tray and measure what arrives."}}]},"es-US":{"summary":"Usar una bandeja y la mitad del agua","visibleChanges":["Prueba de media taza dentro de una bandeja"],"blocks":[{"id":"safety-5","kind":"safety_notice","version":1,"required":true,"data":{"title":"Contengan el agua","text":"Realicen toda la prueba dentro de una bandeja estable lejos de electricidad."}},{"id":"step-5a","kind":"instruction","version":1,"required":true,"data":{"eyebrow":"Versión con menos desorden","title":"Muevan media taza","text":"Hagan una prueba de media taza en la bandeja y midan cuánto llegó."}}]}}'::jsonb, 'none', true, '{"scope":"synthetic-evaluation","humanApprovalClaimed":false}'::jsonb),
  ('ACT-0011-ADAPT-TWO', 'ACT-0011@1.0.0', '{"en-US":{"summary":"Compare two materials","visibleChanges":["Use two labeled cups while preserving equal amounts and stirring"],"blocks":[{"id":"safety-11","kind":"safety_notice","version":1,"required":true,"data":{"title":"Observe, do not taste","text":"Use room-temperature water and do not taste the samples."}},{"id":"step-11a","kind":"instruction","version":1,"required":true,"data":{"eyebrow":"Short comparison","title":"Test two materials","text":"Use equal water and equal stirring to compare two labeled solids."}}]},"es-US":{"summary":"Comparar dos materiales","visibleChanges":["Usar dos vasos etiquetados conservando cantidades y mezcla iguales"],"blocks":[{"id":"safety-11","kind":"safety_notice","version":1,"required":true,"data":{"title":"Observar, no probar","text":"Usen agua a temperatura ambiente y no prueben las muestras."}},{"id":"step-11a","kind":"instruction","version":1,"required":true,"data":{"eyebrow":"Comparación corta","title":"Prueben dos materiales","text":"Usen igual cantidad de agua y de mezcla para comparar dos sólidos etiquetados."}}]}}'::jsonb, 'none', true, '{"scope":"synthetic-evaluation","humanApprovalClaimed":false}'::jsonb)
insert into public.kids_activity_chunk (chunk_id, activity_version_id, locale, chunk_type, label, content, embedding_model, embedding_version, embedding) values
  ('ACT-0001-en-step', 'ACT-0001@1.0.0', 'en-US', 'troubleshooting', 'Paper Bridge · current step', 'If the bridge falls immediately, verify that the supports are stable, the gap is 15 cm, and the cup is empty and centered before adding crayons.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0001-en-safety', 'ACT-0001@1.0.0', 'en-US', 'safety', 'Paper Bridge · safety', 'The adult moves supports and centers the cup. Children add one crayon at a time and keep hands and faces out from below.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0001-es-step', 'ACT-0001@1.0.0', 'es-US', 'troubleshooting', 'Puente de papel · paso actual', 'Si el puente cae de inmediato, comprueba que los apoyos estén estables, la distancia sea 15 cm y el vaso esté vacío y centrado.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0001-es-safety', 'ACT-0001@1.0.0', 'es-US', 'safety', 'Puente de papel · seguridad', 'El adulto mueve los apoyos y centra el vaso. Los niños añaden un crayón por turno y no ponen manos ni cara debajo.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0002-en', 'ACT-0002@1.0.0', 'en-US', 'troubleshooting', 'Seed Sorter · guidance', 'If categories overlap, name one observable property and sort every seed using only that property. Exceptions can form a separate unsure group.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0002-es', 'ACT-0002@1.0.0', 'es-US', 'troubleshooting', 'Clasificador de semillas · guía', 'Si las categorías se mezclan, nombren una propiedad observable y clasifiquen cada semilla usando solo esa propiedad. Las excepciones pueden ir en un grupo de dudas.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0003-en', 'ACT-0003@1.0.0', 'en-US', 'safety', 'Conductivity Tester · safety', 'Stop if any wire is hot, damaged, wet, or if a component is not on the approved list. Disconnect the battery before changing test objects.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0003-es', 'ACT-0003@1.0.0', 'es-US', 'safety', 'Probador de conductividad · seguridad', 'Detengan la actividad si un cable está caliente, dañado o mojado, o si un componente no está aprobado. Desconecten la batería antes de cambiar objetos.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0004-en', 'ACT-0004@1.0.0', 'en-US', 'troubleshooting', 'Hovercraft · troubleshooting', 'If it does not glide, verify the surface is smooth, the opening is centered, and air can escape. Stop if the balloon tears.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0004-es', 'ACT-0004@1.0.0', 'es-US', 'troubleshooting', 'Aerodeslizador · solución', 'Si no se desliza, comprueben que la superficie sea lisa, la abertura esté centrada y el aire pueda salir. Deténganse si el globo se rompe.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0005-en', 'ACT-0005@1.0.0', 'en-US', 'troubleshooting', 'Water Transporter · troubleshooting', 'If little water arrives, inspect one connection at a time inside the tray. Do not add pressure or unapproved tubing.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0005-es', 'ACT-0005@1.0.0', 'es-US', 'troubleshooting', 'Transportador de agua · solución', 'Si llega poca agua, revisen una unión por vez dentro de la bandeja. No añadan presión ni tubos no aprobados.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0006-en', 'ACT-0006@1.0.0', 'en-US', 'troubleshooting', 'Limited Tower · guidance', 'If the tower falls, keep the same twelve pieces and compare base width, symmetry, and the location of heavier pieces.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0006-es', 'ACT-0006@1.0.0', 'es-US', 'troubleshooting', 'Torre limitada · guía', 'Si la torre cae, mantengan las mismas doce piezas y comparen el ancho de la base, la simetría y la posición de las piezas pesadas.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0007-en', 'ACT-0007@1.0.0', 'en-US', 'troubleshooting', 'Static Message · troubleshooting', 'Static charge works best with dry materials. Repeat the same number of rubs and hold the charged object close without touching.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0007-es', 'ACT-0007@1.0.0', 'es-US', 'troubleshooting', 'Mensaje estático · solución', 'La carga estática funciona mejor con materiales secos. Repitan el mismo número de frotamientos y acerquen el objeto sin tocar.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0008-en', 'ACT-0008@1.0.0', 'en-US', 'troubleshooting', 'Cargo Ship · troubleshooting', 'If the boat sinks immediately, inspect for tears and test the empty hull. Spread equal counters across the base rather than stacking them.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0008-es', 'ACT-0008@1.0.0', 'es-US', 'troubleshooting', 'Barco de carga · solución', 'Si el barco se hunde de inmediato, revisen si hay roturas y prueben el casco vacío. Distribuyan fichas iguales sobre la base.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0009-en', 'ACT-0009@1.0.0', 'en-US', 'troubleshooting', 'Cardboard Pulley · troubleshooting', 'If the wheel does not turn, stop pulling and inspect alignment with no load. Do not increase the load or wrap cord around a hand.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0009-es', 'ACT-0009@1.0.0', 'es-US', 'troubleshooting', 'Polea de cartón · solución', 'Si la rueda no gira, dejen de tirar y revisen la alineación sin carga. No aumenten el peso ni enrollen el cordón en la mano.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0010-en', 'ACT-0010@1.0.0', 'en-US', 'troubleshooting', 'Germination · troubleshooting', 'If no change appears, verify moisture without flooding, labels, and elapsed days. Do not open or smell a moldy sample; seal and discard it.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0010-es', 'ACT-0010@1.0.0', 'es-US', 'troubleshooting', 'Germinación · solución', 'Si no hay cambios, revisen la humedad sin inundar, las etiquetas y los días transcurridos. No abran ni huelan una muestra con moho; séllenla y deséchenla.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0011-en', 'ACT-0011@1.0.0', 'en-US', 'troubleshooting', 'Dissolving Detective · guidance', 'If comparisons are unclear, confirm equal water, equal solid amounts, equal stirring and readable labels. Do not heat or taste any sample.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0011-es', 'ACT-0011@1.0.0', 'es-US', 'troubleshooting', 'Detectives de disolución · guía', 'Si la comparación no es clara, comprueben que haya igual cantidad de agua y sólido, igual mezcla y etiquetas legibles. No calienten ni prueben las muestras.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0012-en', 'ACT-0012@1.0.0', 'en-US', 'troubleshooting', 'Build It From My Words · guidance', 'If the designs differ, compare one position at a time and replace vague words with an observable relation such as above, beside, touching, or turned.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0012-es', 'ACT-0012@1.0.0', 'es-US', 'troubleshooting', 'Constrúyelo con mis palabras · guía', 'Si los diseños son distintos, comparen una posición por vez y sustituyan palabras vagas por relaciones observables como arriba, al lado, tocando o girado.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0013-en', 'ACT-0013@1.0.0', 'en-US', 'troubleshooting', 'Balance Path · guidance', 'If the path feels unsafe, stop, remove loose or raised markers, widen turns, and walk slowly on a clear nonslip floor.', 'openai/text-embedding-3-small', 'pending', null),
  ('ACT-0013-es', 'ACT-0013@1.0.0', 'es-US', 'troubleshooting', 'Camino de equilibrio · guía', 'Si el recorrido no se siente seguro, deténganse, quiten marcas sueltas o elevadas, amplíen los giros y caminen despacio sobre un piso despejado y estable.', 'openai/text-embedding-3-small', 'pending', null)
