begin;



-- Generated from the canonical bilingual synthetic catalog.

-- No embedding-provider call is claimed; vectors remain NULL.

on conflict (activity_id) do update set slug = excluded.slug, working_title = excluded.working_title, ownership = excluded.ownership;

on conflict (activity_version_id) do update set activity_id = excluded.activity_id, semantic_version = excluded.semantic_version, status = excluded.status, release_channel = excluded.release_channel, content_hash = excluded.content_hash, snapshot = excluded.snapshot, schema_version = excluded.schema_version, source_locale = excluded.source_locale, core_v2 = excluded.core_v2, risk_level = excluded.risk_level, published_at = excluded.published_at;

on conflict (activity_version_id, locale) do update set locale_payload = excluded.locale_payload, content_hash = excluded.content_hash, completeness = excluded.completeness, reviewed_by = excluded.reviewed_by, reviewed_at = excluded.reviewed_at;

on conflict (activity_version_id, locale, block_id) do update set kind = excluded.kind, block_version = excluded.block_version, required = excluded.required, position = excluded.position, data = excluded.data;

on conflict (adaptation_id) do update set activity_version_id = excluded.activity_version_id, localized_content = excluded.localized_content, safety_impact = excluded.safety_impact, requires_confirmation = excluded.requires_confirmation, approval_record = excluded.approval_record;

on conflict (chunk_id) do update set activity_version_id = excluded.activity_version_id, locale = excluded.locale, chunk_type = excluded.chunk_type, label = excluded.label, content = excluded.content, embedding_model = excluded.embedding_model, embedding_version = excluded.embedding_version, embedding = excluded.embedding;

update public.kids_activity_version set status = 'published', published_at = now() where release_channel = 'synthetic-demo' and status = 'draft';

update public.kids_activity a set active_version_id = av.activity_version_id from public.kids_activity_version av where av.activity_id = a.activity_id and av.release_channel = 'synthetic-demo' and av.status = 'published';



commit;

